-- dashboard.account_balance source

CREATE OR REPLACE VIEW dashboard.account_balance
AS SELECT coa_agg.parent AS "GL Head",
    coa_agg.name AS "GL Name",
    balance.account_name AS "Account Name",
        CASE
            WHEN coa_agg.parent::text ~~ '%ASSET%'::text OR coa_agg.parent::text ~~ '%EXP%'::text THEN
            CASE
                WHEN balance.bal < 0::numeric THEN ('('::text || replace(round(balance.bal, 2)::text, '-'::text, ''::text)) || ')'::text
                ELSE round(balance.bal, 2)::text
            END
            ELSE ''::text
        END AS "Debit",
        CASE
            WHEN coa_agg.parent::text ~~ '%LIAB%'::text OR coa_agg.parent::text ~~ '%INCOME%'::text THEN
            CASE
                WHEN balance.bal < 0::numeric THEN ('('::text || replace(round(balance.bal, 2)::text, '-'::text, ''::text)) || ')'::text
                ELSE round(balance.bal, 2)::text
            END
            ELSE ''::text
        END AS "Credit",
    balance.bal * '-1'::integer::numeric AS "Balance",
    cur.name AS "Currency"
   FROM ( SELECT wtype.id,
            wtype.parentglid,
            wtype.name AS account_name,
            wbalance.instancetype,
            wbalance.currencyid,
            sum(wbalance.totalbalance) * '-1'::integer::numeric AS bal
           FROM walletbalance wbalance
             JOIN wallettype wtype ON wtype.id::text = wbalance.wallettypeid::text
          GROUP BY wtype.id, wtype.parentglid, wtype.name, wbalance.instancetype, wbalance.currencyid) balance
     LEFT JOIN ( SELECT t1.id,
            t1.name,
            t1.description,
            'ASSET'::text AS category,
            ( SELECT DISTINCT coa.name
                   FROM coa
                  WHERE coa.name::text = 'ASSET'::text) AS parent,
            t1.coacode,
            t1.creditamount,
            t1.debitamount,
            ( SELECT currency.name
                   FROM currency
                  WHERE t1.currencyid::text = currency.id::text) AS currency
           FROM coa t1
          WHERE t1.coacode::text ~~ concat(( SELECT DISTINCT coa.coacode::numeric AS coacode
                   FROM coa
                  WHERE coa.name::text = 'ASSET'::text), '%')
        UNION
         SELECT t1.id,
            t1.name,
            t1.description,
            'INCOME'::text AS category,
            ( SELECT DISTINCT coa.name
                   FROM coa
                  WHERE coa.name::text = 'INCOME'::text) AS parent,
            t1.coacode,
            t1.creditamount,
            t1.debitamount,
            ( SELECT currency.name
                   FROM currency
                  WHERE t1.currencyid::text = currency.id::text) AS currency
           FROM coa t1
          WHERE t1.coacode::text ~~ concat(( SELECT DISTINCT coa.coacode::numeric AS coacode
                   FROM coa
                  WHERE coa.name::text = 'INCOME'::text), '%')
        UNION
         SELECT t1.id,
            t1.name,
            t1.description,
            'LIABILITY'::text AS category,
            ( SELECT DISTINCT coa.name
                   FROM coa
                  WHERE coa.name::text = 'LIABILITY'::text) AS parent,
            t1.coacode,
            t1.creditamount,
            t1.debitamount,
            ( SELECT currency.name
                   FROM currency
                  WHERE t1.currencyid::text = currency.id::text) AS currency
           FROM coa t1
          WHERE t1.coacode::text ~~ concat(( SELECT DISTINCT coa.coacode::numeric AS coacode
                   FROM coa
                  WHERE coa.name::text = 'LIABILITY'::text), '%')
        UNION
         SELECT t1.id,
            t1.name,
            t1.description,
            'EXPENDITURE'::text AS category,
            ( SELECT DISTINCT coa.name
                   FROM coa
                  WHERE coa.name::text = 'EXPENDITURE'::text) AS parent,
            t1.coacode,
            t1.creditamount,
            t1.debitamount,
            ( SELECT currency.name
                   FROM currency
                  WHERE t1.currencyid::text = currency.id::text) AS currency
           FROM coa t1
          WHERE t1.coacode::text ~~ concat(( SELECT DISTINCT coa.coacode::numeric AS coacode
                   FROM coa
                  WHERE coa.name::text = 'EXPENDITURE'::text), '%')
  ORDER BY 5) coa_agg ON coa_agg.id::text = balance.parentglid::text
     LEFT JOIN currency cur ON cur.id::text = balance.currencyid::text
  ORDER BY (
        CASE
            WHEN coa_agg.parent::text = 'ASSET'::text THEN 1
            WHEN coa_agg.parent::text = 'LIABILITY'::text THEN 2
            WHEN coa_agg.parent::text = 'INCOME'::text THEN 3
            WHEN coa_agg.parent::text = 'EXPENDITURE'::text THEN 4
            ELSE NULL::integer
        END);


-- dashboard.account_balance_historical source

CREATE OR REPLACE VIEW dashboard.account_balance_historical
AS SELECT t.createdon::date AS createdon,
    t.name AS "Name",
    t.coregltype AS "Core GL Type",
    round(t.creditamount, 2) AS "Credit Amount",
    round(t.debitamount, 2) AS "Debit Amount",
    round(t.totalbalance, 2) AS "Total Balance",
    t.glaccountnumber AS "GL Account No.",
    t.row_num AS "Row Num"
   FROM ( SELECT coaaccountbalancedata.createdon,
            coaaccountbalancedata.name,
            coaaccountbalancedata.coregltype,
            coaaccountbalancedata.creditamount,
            coaaccountbalancedata.debitamount,
            coaaccountbalancedata.totalbalance,
            coaaccountbalancedata.glaccountnumber,
            row_number() OVER (PARTITION BY coaaccountbalancedata.name ORDER BY coaaccountbalancedata.createdon DESC) AS row_num
           FROM coaaccountbalancedata) t
  WHERE t.row_num = 1
  ORDER BY (t.createdon::date) DESC;


-- dashboard.active_cust source

CREATE OR REPLACE VIEW dashboard.active_cust
AS SELECT u.id AS bankaccountid,
    u.firstname,
    u.middlename AS othername,
    u.lastname,
    u.mobilenumber,
    u.createdon AS registrationdate,
    max(wt.txtime) AS transactiondateandtime,
    count(wt.id) AS nooftransactions
   FROM users u
     LEFT JOIN wallettransactions wt ON u.id::text = wt.fromortouserid::text
  GROUP BY u.id;


-- dashboard.active_user_login_report source

CREATE OR REPLACE VIEW dashboard.active_user_login_report
AS SELECT DISTINCT users.walletfunded AS "Wallet Funded",
    users.mobilenumber AS "Mobile No.",
    users.idtype AS "ID Type",
    users.idnumber AS "ID Number",
    users.userstatus AS "User Status",
    to_char(users.lastlogin, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Last Login",
    users.transactionsource AS "Transaction Source",
    users.location AS "Location",
    users.firstname AS "First Name",
    users.middlename AS "Middle Name",
    users.lastname AS "Last Name",
    users.username AS "User Name",
    users.roletype AS "Role",
    users.channel AS "Channel",
        CASE
            WHEN users.roletype::text = 'BUSINESS_ASSOCIATE'::text THEN concat(users.firstname, ' ', users.location)
            ELSE concat(users.firstname, ' ', users.lastname)
        END AS "Name"
   FROM users
  WHERE users.userstatus::text = 'ACTIVE'::text AND users.roletype::text <> 'OPERATION'::text AND date(users.lastlogin) >= (CURRENT_DATE - '180 days'::interval)
  ORDER BY (to_char(users.lastlogin, 'yyyy-mm-dd HH24:MI:SS'::text));


-- dashboard.active_user_transaction_report source

CREATE OR REPLACE VIEW dashboard.active_user_transaction_report
AS SELECT users.mobilenumber AS "Mobile Number",
    users.idtype AS "ID Type",
    users.idnumber AS "ID Number",
    users.transactionsource AS "Transaction Source",
    to_char(users.lasttransactionon, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Last Transaction On",
    to_char(wt.txtime, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Transaction Time",
        CASE
            WHEN users.roletype::text = 'BUSINESS_ASSOCIATE'::text THEN concat(users.firstname, ' ', users.location)
            ELSE concat(users.firstname, ' ', users.lastname)
        END AS "Name",
    users.firstname AS "First Name",
    users.middlename AS "Middle Name",
    users.lastname AS "Last Name",
    users.location AS "Location",
    users.username AS "UserName",
    users.roletype AS "Role",
    channel.name AS "Channel Name"
   FROM ( SELECT t.ownerid,
            t.txtime,
            t.channelid,
            t.row_num
           FROM ( SELECT wallettransactions.ownerid,
                    wallettransactions.txtime,
                    wallettransactions.channelid,
                    row_number() OVER (PARTITION BY wallettransactions.ownerid ORDER BY wallettransactions.txtime DESC) AS row_num
                   FROM wallettransactions) t
          WHERE t.row_num = 1
          ORDER BY t.txtime DESC) wt
     JOIN channel ON wt.channelid::text = channel.id::text
     JOIN users ON users.id::text = wt.ownerid::text
  WHERE users.roletype::text <> 'OPERATION'::text AND users.userstatus::text = 'ACTIVE'::text AND date(wt.txtime) >= (CURRENT_DATE - '180 days'::interval);


-- dashboard.autosweep source

CREATE OR REPLACE VIEW dashboard.autosweep
AS SELECT us.username AS "Merchant ID",
    us.firstname AS "Merchant Name",
    wtbt.payeeaccountnumber AS "Account Number",
    round(wtbt.amount::numeric, 2) AS "Amount Of Sweep",
    date(wtbt.createdon) AS "Date Of Sweep",
    'From Absa wallet to Bank Account'::text AS "Description",
    rl.roletype AS "Role Type",
    rl.name AS "Role Name"
   FROM autosweeptxdetails atd
     LEFT JOIN wallettobanktxdetails wtbt ON atd.executionid::text = wtbt.executionid::text
     LEFT JOIN users us ON wtbt.userid::text = us.id::text
     LEFT JOIN role rl ON us.roleid::text = rl.id::text
  WHERE lower(atd.transactionstatus::text) = 'processed'::text
  ORDER BY wtbt.createdon DESC;


-- dashboard.blocked_users source

CREATE OR REPLACE VIEW dashboard.blocked_users
AS SELECT usr.id AS userid,
    usr.username,
    usr.userstatus,
    audt.modifiedby AS blockedbyid,
    audt.blockedbyname,
    to_char(audt.modifiedon, 'yyyy-mm-dd HH24:MI:SS'::text) AS blockedat,
    rol.name AS rolename,
    rol.roletype,
    audt.remarks
   FROM ( SELECT users.id,
            users.username,
            users.userstatus,
            users.roleid
           FROM users
          WHERE users.userstatus::text ~~ '%BLOCK%'::text) usr
     LEFT JOIN ( SELECT ua.id,
            ua.modifiedby,
            u.username::text AS blockedbyname,
            ua.modifiedon,
            ua.remarks
           FROM usersaudit ua
             JOIN ( SELECT usersaudit.id,
                    max(usersaudit.modifiedon) AS modifiedon
                   FROM usersaudit
                  WHERE lower(usersaudit.userstatus::text) ~~ '%block%'::text
                  GROUP BY usersaudit.id) latestblock ON ua.id::text = latestblock.id::text AND ua.modifiedon = latestblock.modifiedon AND lower(ua.userstatus::text) ~~ '%block%'::text
             JOIN users u ON u.id::text = ua.modifiedby::text) audt ON audt.id::text = usr.id::text
     LEFT JOIN role rol ON rol.id::text = usr.roleid::text;


-- dashboard.cust_reg source

CREATE OR REPLACE VIEW dashboard.cust_reg
AS SELECT users.nationalid AS idnumber,
    users.nationalid AS customerid,
    users.firstname,
    users.middlename AS othername,
    users.lastname,
    users.gender,
    users.mobilenumber,
    users.createdon AS registrationdate,
    users.dob AS dateofbirth
   FROM users
  WHERE users.userstatus::text = 'ACTIVE'::text;


-- dashboard.customer_kyc_info source

CREATE OR REPLACE VIEW dashboard.customer_kyc_info
AS WITH jsondoc AS (
         SELECT userkyc.userid,
            userkyc.kycdocumenttype,
            userkyc.kycprooftype,
            userkyc.lastmodifedon AS lastmodifiedon,
            each_attr.value ->> 'orignalFileName'::text AS kycdocumentname,
            each_attr.value ->> 'uploadedOn'::text AS uploadedon,
            row_number() OVER (PARTITION BY userkyc.userid, userkyc.kycdocumenttype ORDER BY (each_attr.value ->> 'uploadedOn'::text) DESC) AS row_num,
            count(1) OVER (PARTITION BY userkyc.userid, userkyc.kycdocumenttype) AS documentversion
           FROM userkyc
             CROSS JOIN LATERAL unnest(ARRAY[userkyc.kycdocumentlistjson::json]) each_doc(each_doc)
             CROSS JOIN LATERAL json_array_elements(each_doc.each_doc) each_attr(value)
        )
 SELECT row_number() OVER () AS sno,
    u.id,
    u.createdby,
    u.username AS "User Name",
    u.firstname AS "First Name",
    u.middlename AS "Middle Name",
    u.lastname AS "Last Name",
    u.mobilenumber AS "Mobile Number",
    to_char(u.createdon, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Registration Date",
    u.email AS "Email",
    to_char(u.dob, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Date of Birth",
    u.gender AS "Gender",
    userenhancekyc.address AS "Postal Address",
    userenhancekyc.address2 AS "Physical Address",
    u.countrycode AS "Country Code",
    userkycdetails.areacode AS "City Pincode",
    u.userstatus AS "User Status",
    u.roletype AS "Role Type",
    u.idtype AS "ID Type",
    u.idnumber AS "ID Number",
    u.riskrating AS "Risk Rating",
    u.country AS "Country",
    u.netrevealstatus AS "Sanction Screening",
    u.ldapuser,
    userenhancekyc.employmenttype AS "Employee Type",
    userenhancekyc.taxnumber AS "Tax Number",
    userenhancekyc.monthlyincome AS "Monthly Income",
    userenhancekyc.nationality AS "Nationality",
    userenhancekyc.occupation AS "Occupation",
    userenhancekyc.userid,
    r.name AS "Role Name",
    urf.referredby AS "Referred By",
    ukc.documenttypes AS "KYC Documents Type",
    ukc.kycprooftype AS "KYC Proof Types",
    ukc.documentversion AS "KYC Document Version",
    ukc.kycdocumentsname AS "KYC Document Name",
    to_char(uekycad.createdon, 'yyyy-mm-dd HH24:MI:SS'::text) AS "KYC Upgrade Request Date",
    to_char(uekycad.modifiedon, 'yyyy-mm-dd HH24:MI:SS'::text) AS "KYC Approve Request Date",
    uekycad.kycapproveruser AS "KYC Approver User",
    nu.username AS "Registered by Agent",
        CASE
            WHEN u.registrationviaweb IS TRUE THEN 'True'::text
            ELSE 'False'::text
        END AS "Registration via web",
        CASE
            WHEN u2.kamelresponsejson::text = ''::text THEN 'N/A'::text
            WHEN (u2.kamelresponsejson::json ->> 'error'::text) = 'false'::text THEN 'ETB'::text
            ELSE 'NTB'::text
        END AS "Customertype",
        CASE
            WHEN u2.kamelresponsejson::text = ''::text THEN 'N/A'::text
            WHEN ((u2.kamelresponsejson::json -> 'manualKYCStatus'::text)::text) = '"Yes"'::text THEN '"Yes"'::text
            WHEN ((u2.kamelresponsejson::json -> 'manualKYCStatus'::text)::text) = '"No"'::text THEN '"No"'::text
            WHEN ((u2.kamelresponsejson::json -> 'systemKYCStatus'::text)::text) = '"Yes"'::text THEN '"Yes"'::text
            WHEN ((u2.kamelresponsejson::json -> 'systemKYCStatus'::text)::text) = '"No"'::text THEN '"No"'::text
            ELSE '"No"'::text
        END AS "KYC compliant"
   FROM users u
     LEFT JOIN userenhancekyc ON userenhancekyc.userid::text = u.id::text
     LEFT JOIN userselfregisterdata u2 ON u2.mobilenumber::text = u.mobilenumber::text
     LEFT JOIN role r ON u.roleid::text = r.id::text
     LEFT JOIN userkycdetails ON userkycdetails.userid::text = u.id::text
     LEFT JOIN ( SELECT u_1.username AS usrname,
            uekycad_1.status,
            uekycad_1.createdby,
            uekycad_1.createdon,
            uekycad_1.modifiedon,
            ( SELECT users.username
                   FROM users
                  WHERE users.id::text = uekycad_1.modifiedby::text) AS kycapproveruser
           FROM userenhancekycaudit uekycad_1
             JOIN ( SELECT userenhancekycaudit.createdby,
                    max(userenhancekycaudit.modifiedon) AS modifiedon
                   FROM userenhancekycaudit
                  WHERE userenhancekycaudit.status::text = 'APPROVED'::text
                  GROUP BY userenhancekycaudit.createdby) t ON t.createdby::text = uekycad_1.createdby::text AND t.modifiedon = uekycad_1.modifiedon
             LEFT JOIN users u_1 ON u_1.id::text = uekycad_1.createdby::text) uekycad ON u.id::text = uekycad.createdby::text
     LEFT JOIN ( SELECT nu_1.createdby,
            nu_1.username,
            nu_1.id,
            r_1.name
           FROM users nu_1
             LEFT JOIN role r_1 ON nu_1.roleid::text = r_1.id::text AND r_1.name::text ~~ '%Agent%'::text
             JOIN ( SELECT users.createdby,
                    max(users.createdon) AS createdon
                   FROM users
                  GROUP BY users.createdby) t ON t.createdby::text = nu_1.createdby::text AND t.createdon = nu_1.createdon) nu ON u.createdby::text = nu.id::text
     LEFT JOIN ( SELECT urf_1.referraluserid,
            urf_1.refereeuserid,
            u_1.username AS referredby
           FROM userreferral urf_1
             LEFT JOIN users u_1 ON u_1.id::text = urf_1.refereeuserid::text) urf ON u.id::text = urf.referraluserid::text
     LEFT JOIN ( SELECT jsondoc.userid,
            string_agg(jsondoc.kycdocumenttype::text, ','::text ORDER BY jsondoc.lastmodifiedon DESC) AS documenttypes,
            string_agg(jsondoc.kycprooftype::text, ','::text ORDER BY jsondoc.lastmodifiedon DESC) AS kycprooftype,
            string_agg(jsondoc.kycdocumentname, ','::text ORDER BY jsondoc.lastmodifiedon DESC) AS kycdocumentsname,
            max(jsondoc.documentversion) AS documentversion
           FROM jsondoc
          WHERE jsondoc.row_num = 1
          GROUP BY jsondoc.userid) ukc ON ukc.userid::text = u.id::text;


-- dashboard.customer_kyc_info_bostwana source

CREATE OR REPLACE VIEW dashboard.customer_kyc_info_bostwana
AS WITH jsondoc AS (
         SELECT userkyc.userid,
            userkyc.kycdocumenttype,
            userkyc.kycprooftype,
            userkyc.lastmodifedon AS lastmodifiedon,
            each_attr.value ->> 'orignalFileName'::text AS kycdocumentname,
            each_attr.value ->> 'uploadedOn'::text AS uploadedon,
            row_number() OVER (PARTITION BY userkyc.userid, userkyc.kycdocumenttype ORDER BY (each_attr.value ->> 'uploadedOn'::text) DESC) AS row_num,
            count(1) OVER (PARTITION BY userkyc.userid, userkyc.kycdocumenttype) AS documentversion
           FROM userkyc
             CROSS JOIN LATERAL unnest(ARRAY[userkyc.kycdocumentlistjson::json]) each_doc(each_doc)
             CROSS JOIN LATERAL json_array_elements(each_doc.each_doc) each_attr(value)
        )
 SELECT row_number() OVER () AS sno,
    u.id,
    u.createdby,
    ua.username AS "Createdby",
    u.username AS "User Name",
    u.firstname AS "First Name",
    u.middlename AS "Middle Name",
    u.lastname AS "Last Name",
    u.mobilenumber AS "Mobile Number",
    to_char(u.createdon, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Registration Date",
    u.email AS "Email",
    to_char(u.dob, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Date of Birth",
    u.gender AS "Gender",
    userenhancekyc.address AS "Postal Address",
    userenhancekyc.address2 AS "Physical Address",
    u.countrycode AS "Country Code",
    userkycdetails.areacode AS "City Pincode",
    u.userstatus AS "User Status",
    u.roletype AS "Role Type",
    u.idtype AS "ID Type",
    u.idnumber AS "ID Number",
    u.riskrating AS "Risk Rating",
    u.country AS "Country",
    u.netrevealstatus AS "Sanction Screening",
    u.ldapuser,
    userenhancekyc.employmenttype AS "Employee Type",
    userenhancekyc.taxnumber AS "Tax Number",
    userenhancekyc.monthlyincome AS "Monthly Income",
    userenhancekyc.nationality AS "Nationality",
    userenhancekyc.occupation AS "Occupation",
    userenhancekyc.userid,
    r.name AS "Role Name",
    urf.referredby AS "Referred By",
    ukc.documenttypes AS "KYC Documents Type",
    ukc.kycprooftype AS "KYC Proof Types",
    ukc.documentversion AS "KYC Document Version",
    ukc.kycdocumentsname AS "KYC Document Name",
    to_char(uekycad.createdon, 'yyyy-mm-dd HH24:MI:SS'::text) AS "KYC Upgrade Request Date",
    to_char(uekycad.modifiedon, 'yyyy-mm-dd HH24:MI:SS'::text) AS "KYC Approve Request Date",
    uekycad.kycapproveruser AS "KYC Approver User",
    nu.username AS "Registered by Agent",
    u.sourceoffund AS "Source of Funds",
    u.referencenumber AS "Refrence",
        CASE
            WHEN u.registrationviaweb IS TRUE THEN 'True'::text
            ELSE 'False'::text
        END AS "Registration via web",
        CASE
            WHEN u2.kamelresponsejson::text = ''::text THEN 'N/A'::text
            WHEN (u2.kamelresponsejson::json ->> 'error'::text) = 'false'::text THEN 'ETB'::text
            ELSE 'NTB'::text
        END AS "Customertype",
        CASE
            WHEN u2.kamelresponsejson::text = ''::text THEN 'N/A'::text
            WHEN ((u2.kamelresponsejson::json -> 'manualKYCStatus'::text)::text) = '"Yes"'::text THEN '"Yes"'::text
            WHEN ((u2.kamelresponsejson::json -> 'manualKYCStatus'::text)::text) = '"No"'::text THEN '"No"'::text
            WHEN ((u2.kamelresponsejson::json -> 'systemKYCStatus'::text)::text) = '"Yes"'::text THEN '"Yes"'::text
            WHEN ((u2.kamelresponsejson::json -> 'systemKYCStatus'::text)::text) = '"No"'::text THEN '"No"'::text
            ELSE '"No"'::text
        END AS "KYC compliant"
   FROM users u
     LEFT JOIN users ua ON ua.id::text = u.createdby::text
     LEFT JOIN userenhancekyc ON userenhancekyc.userid::text = u.id::text
     LEFT JOIN userselfregisterdata u2 ON u2.mobilenumber::text = u.mobilenumber::text
     LEFT JOIN role r ON u.roleid::text = r.id::text
     LEFT JOIN userkycdetails ON userkycdetails.userid::text = u.id::text
     LEFT JOIN ( SELECT u_1.username AS usrname,
            uekycad_1.status,
            uekycad_1.createdby,
            uekycad_1.createdon,
            uekycad_1.modifiedon,
            ( SELECT users.username
                   FROM users
                  WHERE users.id::text = uekycad_1.modifiedby::text) AS kycapproveruser
           FROM userenhancekycaudit uekycad_1
             JOIN ( SELECT userenhancekycaudit.createdby,
                    max(userenhancekycaudit.modifiedon) AS modifiedon
                   FROM userenhancekycaudit
                  WHERE userenhancekycaudit.status::text = 'APPROVED'::text
                  GROUP BY userenhancekycaudit.createdby) t ON t.createdby::text = uekycad_1.createdby::text AND t.modifiedon = uekycad_1.modifiedon
             LEFT JOIN users u_1 ON u_1.id::text = uekycad_1.createdby::text) uekycad ON u.id::text = uekycad.createdby::text
     LEFT JOIN ( SELECT nu_1.createdby,
            nu_1.username,
            nu_1.id,
            r_1.name
           FROM users nu_1
             LEFT JOIN role r_1 ON nu_1.roleid::text = r_1.id::text AND r_1.name::text ~~ '%Agent%'::text
             JOIN ( SELECT users.createdby,
                    max(users.createdon) AS createdon
                   FROM users
                  GROUP BY users.createdby) t ON t.createdby::text = nu_1.createdby::text AND t.createdon = nu_1.createdon) nu ON u.createdby::text = nu.id::text
     LEFT JOIN ( SELECT urf_1.referraluserid,
            urf_1.refereeuserid,
            u_1.username AS referredby
           FROM userreferral urf_1
             LEFT JOIN users u_1 ON u_1.id::text = urf_1.refereeuserid::text) urf ON u.id::text = urf.referraluserid::text
     LEFT JOIN ( SELECT jsondoc.userid,
            string_agg(jsondoc.kycdocumenttype::text, ','::text ORDER BY jsondoc.lastmodifiedon DESC) AS documenttypes,
            string_agg(jsondoc.kycprooftype::text, ','::text ORDER BY jsondoc.lastmodifiedon DESC) AS kycprooftype,
            string_agg(jsondoc.kycdocumentname, ','::text ORDER BY jsondoc.lastmodifiedon DESC) AS kycdocumentsname,
            max(jsondoc.documentversion) AS documentversion
           FROM jsondoc
          WHERE jsondoc.row_num = 1
          GROUP BY jsondoc.userid) ukc ON ukc.userid::text = u.id::text;


