-- dashboard.customer_onboarding_report source

CREATE OR REPLACE VIEW dashboard.customer_onboarding_report
AS SELECT concat(u.firstname, ' ', u.lastname) AS customer_name,
    u.dob,
    u.mobilenumber,
    u.idtype,
    u.idnumber AS idvalue,
    u.netrevealstatus AS sanctions,
    u.riskrating,
    u.riskratingscore AS riskscore,
    u.riskratingdate AS score_timestamp,
    u.username AS cid,
    u.email,
    u.remediationstatus AS status,
    u.userstatus AS employmentstatus,
    u.remediationdate,
    u.createdon AS onboardingdate,
    u.remarks,
    'NOFACE'::text AS channel,
    'DW'::text AS customertype,
    'DWA'::text AS productcode,
    'DW_BW'::text AS sbu,
    u2.occupation,
    u.referencenumber AS e_casa_reference_number,
    ( SELECT concat(u.firstname, ' ', u.lastname) AS concat
          WHERE u.id::text = u.remediationapprover::text) AS approver
   FROM users u
     JOIN userenhancekyc u2 ON u.username::text = u2.username::text
  WHERE u.roletype::text = 'CUSTOMER'::text AND (u.kycstatus::text = ANY (ARRAY['KYC_COMPLETE'::character varying::text, 'KYC_DONE'::character varying::text]));


-- dashboard.data_subject_rights source

CREATE OR REPLACE VIEW dashboard.data_subject_rights
AS SELECT users.username AS "Username",
    concat(users.firstname, ' ', users.lastname) AS "Name",
    users.roletype AS "RoleType",
    users.mobilenumber AS "Mobile Number",
    users.idnumber AS "ID Number",
    users.channel AS "Channel",
    users.optintodatasubjectrights AS "Data Subject Rights",
    users.objectiontoprocessing AS "Objection to Processing",
    users.objectiontoprofiling AS " Objection to Profiling",
        CASE
            WHEN users.contactmethodsms IS TRUE THEN 'True'::text
            ELSE 'False'::text
        END AS "Contact SMS Method",
        CASE
            WHEN users.contactmethodtelephonecall IS TRUE THEN 'True'::text
            ELSE 'False'::text
        END AS "Contact  Mobile Method",
        CASE
            WHEN users.contactmethodemail IS TRUE THEN 'True'::text
            ELSE 'False'::text
        END AS "Contact Email Method",
    to_char(users.dateupdate, 'yyyy-mm-dd HH24:MI:SS'::text) AS "DateUpdate/Correction",
    users.datadeletion AS "Data Deletion",
    to_char(users.modifiedon, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Modified Timestamp"
   FROM users
  WHERE users.roletype::text = 'CUSTOMER'::text;


-- dashboard.dormant_user_report source

CREATE OR REPLACE VIEW dashboard.dormant_user_report
AS SELECT DISTINCT users.walletfunded AS "Wallet Funded",
    users.mobilenumber AS "Mobile No.",
    users.idtype AS "ID Type",
    users.idnumber AS "ID Number",
    users.userstatus AS "User Status",
    to_char(users.lastlogin, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Lastlogin",
    to_char(users.lasttransactionon, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Last transaction on",
    users.transactionsource AS "Transaction Source",
    users.firstname AS "First Name",
    users.middlename AS "Middle Name",
    users.lastname AS "Last Name",
    users.location AS "Location",
    users.username AS "User Name",
    users.roletype AS "Role",
    users.channel AS "Channel",
        CASE
            WHEN users.roletype::text = 'BUSINESS_ASSOCIATE'::text THEN concat(users.firstname, ' ', users.location)
            ELSE concat(users.firstname, ' ', users.lastname)
        END AS "Name"
   FROM users
  WHERE users.userstatus::text = 'DORMANT'::text AND date(users.lastlogin) >= (CURRENT_DATE - '548 days'::interval)
  ORDER BY (to_char(users.lastlogin, 'yyyy-mm-dd HH24:MI:SS'::text));


-- dashboard.dropofstatus source

CREATE OR REPLACE VIEW dashboard.dropofstatus
AS SELECT users.registrationviaweb AS "Registration Via Web",
    users.userstatus AS "User Status",
    users.kycstatus AS "Kyc Status",
    concat(users.firstname, ' ', users.lastname) AS "UserName",
    users.mobilenumber AS "Mobile No.",
    userselfregisterdata.mobilenumber AS "User SelfRegister Mobile No.",
    users.idtype AS "ID Type",
    users.idnumber AS "ID Number",
    to_char(users.lastlogin, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Lastlogin",
    users.securityquestionjson AS "Security Question",
    users.roletype AS "Role",
        CASE
            WHEN users.securityquestionjson IS NOT NULL AND users.kycstatus::text = 'NON_KYC'::text THEN 'KYC Submission Drop off'::text
            WHEN users.securityquestionjson IS NULL THEN 'Registration Drop off'::text
            WHEN users.securityquestionjson IS NOT NULL THEN 'KYC Submission Drop off'::text
            WHEN userselfregisterdata.mobilenumber IS NULL THEN 'Registration Drop off'::text
            ELSE NULL::text
        END AS "Drop Off Stage"
   FROM users
     LEFT JOIN userselfregisterdata ON users.mobilenumber::text = userselfregisterdata.mobilenumber::text
  WHERE users.userstatus::text <> 'DORMANT'::text AND users.userstatus::text <> 'BLOCKED'::text AND users.roletype::text = 'CUSTOMER'::text AND users.kycstatus::text <> 'KYC_COMPLETE'::text AND users.kycstatus::text <> 'KYC_DONE'::text
  ORDER BY users.lastlogin;


-- dashboard.fourglreportstandalone source

CREATE OR REPLACE VIEW dashboard.fourglreportstandalone
AS SELECT expr_qry.coacode AS "COA code",
    expr_qry.parent AS "GL Head",
    expr_qry.name AS "GL Name",
    expr_qry.description AS "Description",
        CASE
            WHEN expr_qry.parent::text ~~ '%ASSET%'::text OR expr_qry.parent::text ~~ '%EXP%'::text THEN
            CASE
                WHEN ((expr_qry.creditamount - expr_qry.debitamount) * '-1'::integer::numeric) < 0::numeric THEN ('('::text || replace(round((expr_qry.creditamount - expr_qry.debitamount) * (- 1::numeric), 2)::text, '-'::text, ''::text)) || ')'::text
                ELSE round((expr_qry.creditamount - expr_qry.debitamount) * '-1'::integer::numeric, 2)::text
            END
            ELSE ''::text
        END AS "Debit",
        CASE
            WHEN expr_qry.parent::text ~~ '%LIAB%'::text OR expr_qry.parent::text ~~ '%INCOME%'::text THEN
            CASE
                WHEN ((expr_qry.creditamount - expr_qry.debitamount) * '-1'::integer::numeric) < 0::numeric THEN ('('::text || replace(round((expr_qry.creditamount - expr_qry.debitamount) * (- 1::numeric), 2)::text, '-'::text, ''::text)) || ')'::text
                ELSE round((expr_qry.creditamount - expr_qry.debitamount) * '-1'::integer::numeric, 2)::text
            END
            ELSE ''::text
        END AS "Credit",
    expr_qry.currency
   FROM ( SELECT t1.name,
            t1.description,
            'ASSET'::text AS category,
            ( SELECT DISTINCT coa.name
                   FROM coa
                  WHERE coa.name::text = 'ASSET'::text) AS parent,
            t1.coacode,
            t1.creditamount,
            t1.debitamount,
            ( SELECT currency.name
                   FROM currency
                  WHERE t1.currencyid::text = currency.id::text) AS currency
           FROM coa t1
          WHERE t1.coacode::text ~~ concat(( SELECT DISTINCT coa.coacode::numeric AS coacode
                   FROM coa
                  WHERE coa.name::text = 'ASSET'::text), '%')
        UNION
         SELECT t1.name,
            t1.description,
            'INCOME'::text AS category,
            ( SELECT DISTINCT coa.name
                   FROM coa
                  WHERE coa.name::text = 'INCOME'::text) AS parent,
            t1.coacode,
            t1.creditamount,
            t1.debitamount,
            ( SELECT currency.name
                   FROM currency
                  WHERE t1.currencyid::text = currency.id::text) AS currency
           FROM coa t1
          WHERE t1.coacode::text ~~ concat(( SELECT DISTINCT coa.coacode::numeric AS coacode
                   FROM coa
                  WHERE coa.name::text = 'INCOME'::text), '%')
        UNION
         SELECT t1.name,
            t1.description,
            'LIABILITY'::text AS category,
            ( SELECT DISTINCT coa.name
                   FROM coa
                  WHERE coa.name::text = 'LIABILITY'::text) AS parent,
            t1.coacode,
            t1.creditamount,
            t1.debitamount,
            ( SELECT currency.name
                   FROM currency
                  WHERE t1.currencyid::text = currency.id::text) AS currency
           FROM coa t1
          WHERE t1.coacode::text ~~ concat(( SELECT DISTINCT coa.coacode::numeric AS coacode
                   FROM coa
                  WHERE coa.name::text = 'LIABILITY'::text), '%')
        UNION
         SELECT t1.name,
            t1.description,
            'EXPENDITURE'::text AS category,
            ( SELECT DISTINCT coa.name
                   FROM coa
                  WHERE coa.name::text = 'EXPENDITURE'::text) AS parent,
            t1.coacode,
            t1.creditamount,
            t1.debitamount,
            ( SELECT currency.name
                   FROM currency
                  WHERE t1.currencyid::text = currency.id::text) AS currency
           FROM coa t1
          WHERE t1.coacode::text ~~ concat(( SELECT DISTINCT coa.coacode::numeric AS coacode
                   FROM coa
                  WHERE coa.name::text = 'EXPENDITURE'::text), '%')
  ORDER BY 5) expr_qry;


-- dashboard.interest_accrual source

CREATE OR REPLACE VIEW dashboard.interest_accrual
AS SELECT rd.rdaccountno AS "Account ID",
    usr.username AS "Mobile No.",
    rd.accountstatus AS "Account Status",
    concat(usr.firstname, ' ', usr.lastname) AS "Name",
    date(da.acuraldonetill) AS "Accrual  Date",
    round(da.dailyaccuralamount, 2)::text AS "Value",
    round(da.totalinterestaccured, 2)::text AS "Total Accrued",
    round(rd.totalamountdeposited, 2)::text AS "Balance",
    round(da.dailyaccuralamount, 2)::text AS "Base Accrued",
    round(rd.bonusamountdisbursed, 2)::text AS "Bonus Accrued"
   FROM depositaccural da
     JOIN users usr ON da.userid::text ~~ usr.id::text
     LEFT JOIN rdproductassociation rd ON da.depositproductassociationid::text ~~ rd.id::text;


-- dashboard.merchant_transaction source

CREATE OR REPLACE VIEW dashboard.merchant_transaction
AS SELECT cr.executionid,
    cr.businesstrxid AS transaction_id,
    dr.username AS payer,
    cr.username AS payee,
    round(dr.debitamount, 2) AS amount,
    to_char(dr.createdon, 'yyyy-mm-dd HH24:MI:SS'::text) AS transaction_date,
    COALESCE(dr.transaction_type, dr.description) AS transaction_type,
    dr.transactionstatus AS transaction_status,
    dr.channel_name,
    dr.rolename AS payer_role,
    cr.rolename AS payee_role,
    dr.roletype AS payer_role_type,
    cr.roletype AS payee_role_type,
    dr.description,
    dr.remarks
   FROM ( SELECT trns.executionid,
            trns.businesstrxid,
            trns.fromortouserid,
                CASE
                    WHEN lower(trns.instancetype::text) ~~ '%business%'::text THEN wtype.name
                    ELSE usr.username
                END AS username,
                CASE
                    WHEN lower(trns.instancetype::text) ~~ '%business%'::text THEN NULL::character varying
                    ELSE rl.name
                END AS rolename,
            rl.roletype,
            trns.debitamount,
            trns.pairid,
            trns.createdon,
            trns.businessproductid AS trns_type_id,
                CASE
                    WHEN trns.parentid IS NULL THEN bp.name
                    ELSE c.name
                END AS transaction_type,
            trns.transactionstatus,
            trns.channelid,
            ch.name AS channel_name,
            trns.description,
            trns.remarks
           FROM ( SELECT wallettransactions.executionid,
                    wallettransactions.businesstrxid,
                        CASE
                            WHEN wallettransactions.instancetype::text = 'CUSTOMER'::text AND (wallettransactions.fromortouserid::text = ''::text OR wallettransactions.fromortouserid IS NULL) THEN wallettransactions.ownerid
                            ELSE wallettransactions.fromortouserid
                        END AS fromortouserid,
                    wallettransactions.debitamount,
                    wallettransactions.creditamount,
                    wallettransactions.pairid,
                    wallettransactions.createdon,
                    wallettransactions.businessproductid,
                    wallettransactions.parentid,
                    wallettransactions.transactionstatus,
                    wallettransactions.wallettypeid,
                    wallettransactions.channelid,
                    wallettransactions.description,
                    wallettransactions.instancetype,
                    wallettransactions.remarks
                   FROM wallettransactions
                  WHERE wallettransactions.debitamount > 0::numeric
                UNION ALL
                 SELECT pendingtransaction.executionid,
                    NULL::character varying AS businesstrxid,
                    pendingtransaction.fromuser AS fromortouserid,
                    pendingtransaction.debitreservedamount AS debitamount,
                    pendingtransaction.creditreservedamount AS creditamount,
                    NULL::character varying AS pairid,
                    pendingtransaction.createdon,
                    pendingtransaction.businessproductid,
                    NULL::character varying AS parentid,
                    pendingtransaction.transactionstatus,
                    pendingtransaction.creditwallettypeid AS wallettypeid,
                    pendingtransaction.channelid,
                    pendingtransaction.description,
                    NULL::character varying AS instancetype,
                    pendingtransaction.remarks
                   FROM pendingtransaction) trns
             LEFT JOIN users usr ON usr.id::text = trns.fromortouserid::text
             LEFT JOIN wallettype wtype ON wtype.id::text = trns.wallettypeid::text
             LEFT JOIN businessproduct bp ON bp.id::text = trns.businessproductid::text
             LEFT JOIN charges c ON c.id::text = trns.businessproductid::text
             LEFT JOIN channel ch ON ch.id::text = trns.channelid::text
             LEFT JOIN role rl ON rl.id::text = usr.roleid::text) dr
     JOIN ( SELECT trns.executionid,
            trns.businesstrxid,
            trns.fromortouserid,
                CASE
                    WHEN lower(trns.instancetype::text) ~~ '%business%'::text THEN wtype.name
                    ELSE usr.username
                END AS username,
                CASE
                    WHEN lower(trns.instancetype::text) ~~ '%business%'::text THEN NULL::character varying
                    ELSE rl.name
                END AS rolename,
            rl.roletype,
            trns.creditamount,
            trns.pairid,
            trns.createdon,
            trns.businessproductid AS trns_type_id,
                CASE
                    WHEN trns.parentid IS NULL THEN bp.name
                    ELSE c.name
                END AS transaction_type,
            trns.transactionstatus,
            trns.channelid,
            ch.name AS channel_name,
            trns.description,
            trns.remarks
           FROM ( SELECT wallettransactions.executionid,
                    wallettransactions.businesstrxid,
                        CASE
                            WHEN wallettransactions.instancetype::text = 'CUSTOMER'::text AND (wallettransactions.fromortouserid::text = ''::text OR wallettransactions.fromortouserid IS NULL) THEN wallettransactions.ownerid
                            ELSE wallettransactions.fromortouserid
                        END AS fromortouserid,
                    wallettransactions.debitamount,
                    wallettransactions.creditamount,
                    wallettransactions.pairid,
                    wallettransactions.createdon,
                    wallettransactions.businessproductid,
                    wallettransactions.parentid,
                    wallettransactions.transactionstatus,
                    wallettransactions.wallettypeid,
                    wallettransactions.channelid,
                    wallettransactions.description,
                    wallettransactions.instancetype,
                    wallettransactions.remarks
                   FROM wallettransactions
                  WHERE wallettransactions.creditamount > 0::numeric
                UNION ALL
                 SELECT pendingtransaction.executionid,
                    NULL::character varying AS businesstrxid,
                    pendingtransaction.touser AS fromortouserid,
                    pendingtransaction.debitreservedamount AS debitamount,
                    pendingtransaction.creditreservedamount AS creditamount,
                    NULL::character varying AS pairid,
                    pendingtransaction.createdon,
                    pendingtransaction.businessproductid,
                    NULL::character varying AS parentid,
                    pendingtransaction.transactionstatus,
                    pendingtransaction.creditwallettypeid AS wallettypeid,
                    pendingtransaction.channelid,
                    pendingtransaction.description,
                    NULL::character varying AS instancetype,
                    pendingtransaction.remarks
                   FROM pendingtransaction) trns
             LEFT JOIN users usr ON usr.id::text = trns.fromortouserid::text
             LEFT JOIN wallettype wtype ON wtype.id::text = trns.wallettypeid::text
             LEFT JOIN businessproduct bp ON bp.id::text = trns.businessproductid::text
             LEFT JOIN charges c ON c.id::text = trns.businessproductid::text
             LEFT JOIN channel ch ON ch.id::text = trns.channelid::text
             LEFT JOIN role rl ON rl.id::text = usr.roleid::text) cr ON cr.executionid::text = dr.executionid::text AND cr.businesstrxid::text = dr.businesstrxid::text AND cr.creditamount = dr.debitamount
  WHERE (lower(cr.roletype::text) ~~ '%business%'::text OR lower(dr.roletype::text) ~~ '%business%'::text) AND (lower(cr.rolename::text) ~~ '%merch%'::text OR lower(dr.rolename::text) ~~ '%merch%'::text)
  ORDER BY dr.createdon DESC;


-- dashboard.ml_cust source

CREATE OR REPLACE VIEW dashboard.ml_cust
AS SELECT users.mobilenumber,
    users.idnumber,
    users.createdon,
    '099'::text AS status,
    'No Data Found for subscriber'::text AS result
   FROM users;


-- dashboard.outstanding_amount_report source

CREATE OR REPLACE VIEW dashboard.outstanding_amount_report
AS SELECT u.username AS merchant_id,
    concat(u.firstname, ' ', u.lastname) AS name,
    u.mobilenumber AS mobile_number,
    u.location,
    u.idnumber AS registration_number,
    l.amount AS outstanding_amount
   FROM lienaccounttxdetails l
     LEFT JOIN users u ON u.id::text = l.userid::text
     LEFT JOIN walletbalance wb ON wb.id::text = l.walletbalanceid::text
  WHERE (l.txstatus::text = 'FAILED'::text OR l.txstatus IS NULL) AND wb.totalbalance <= 0::numeric
  ORDER BY l.createdon DESC;


-- dashboard.pin_status source

CREATE OR REPLACE VIEW dashboard.pin_status
AS SELECT u.country,
    u.mobilenumber,
    u.passwordexpirydate,
        CASE
            WHEN u.passwordexpirydate >= now() THEN 'Active'::text
            ELSE 'Expired'::text
        END AS pin_status,
    u.userstatus AS customer_status
   FROM users u
     JOIN ( SELECT users.mobilenumber,
            max(users.passwordexpirydate) AS pass_exp_at
           FROM users
          GROUP BY users.mobilenumber) exp_pin ON exp_pin.mobilenumber::text = u.mobilenumber::text AND exp_pin.pass_exp_at = u.passwordexpirydate;


-- dashboard.reconcillation source

CREATE OR REPLACE VIEW dashboard.reconcillation
AS WITH cbspool AS (
         SELECT nor.productid,
            nor.productdisplayname,
            nor.producttype,
            nor.counterpartynarrativecr,
            nor.accountnumber,
            nor.accountnumbercr,
            rev.productdisplayname AS productdisplayname_rev,
            rev.producttype AS producttype_rev,
            rev.counterpartynarrativecr AS counterpartynarrativecr_rev,
            rev.accountnumber AS accountnumber_rev,
            rev.accountnumbercr AS accountnumbercr_rev
           FROM ( SELECT cbspoolentity.productid,
                    cbspoolentity.productdisplayname,
                    cbspoolentity.producttype,
                    cbspoolentity.counterpartynarrativecr,
                    cbspoolentity.accountnumber,
                    cbspoolentity.accountnumbercr
                   FROM cbspoolentity
                  WHERE lower(cbspoolentity.counterpartynarrativecr::text) !~~ '%reversal%'::text) nor
             JOIN ( SELECT cbspoolentity.productid,
                    cbspoolentity.productdisplayname,
                    cbspoolentity.producttype,
                    cbspoolentity.counterpartynarrativecr,
                    cbspoolentity.accountnumber,
                    cbspoolentity.accountnumbercr
                   FROM cbspoolentity
                  WHERE lower(cbspoolentity.counterpartynarrativecr::text) ~~ '%reversal%'::text) rev ON nor.productid::text = rev.productid::text
        )
 SELECT row_number() OVER () AS "srlNo",
    cr.executionid,
    cr.transactionid AS "trasactionIDCredit",
    dr.transactionid AS "trasactionIDDebit",
    dr.username AS payer,
    cr.username AS payee,
    round(dr.debitamount, 2) AS amount,
    dr.transactionstatus AS "transactionStatus",
    to_char(timezone('sast'::text, timezone('utc'::text, dr.createdon)), 'yyyy-mm-dd HH:MI:SS'::text) AS "transactionDate",
    COALESCE(dr.transaction_type, dr.description) AS "transactionType",
    dr.channel_name AS "channelName",
    COALESCE(dr.cybersource_trns_id, cr.cybersource_trns_id) AS "cybersourceTransactionID",
    dr.description,
    cr.businesstrxid AS "businessTrasactionID",
    dr.narrative AS "counterpartyNarrative",
    dr.debit_gl_ac_no AS "debitGLAccountNumber",
    cr.credit_gl_ac_no AS "creditGLAccountNumber",
    now() AS "createdOn"
   FROM ( SELECT trns.executionid,
            trns.transactionid,
            trns.businesstrxid,
            trns.fromortouserid,
                CASE
                    WHEN lower(trns.instancetype::text) ~~ '%business%'::text THEN wtype.name
                    ELSE COALESCE(usr.username, wtype.name)
                END AS username,
            rl.name AS rolename,
            trns.debitamount,
            trns.pairid,
            trns.createdon,
            trns.businessproductid AS trns_type_id,
                CASE
                    WHEN trns.parentid IS NULL THEN bp.name
                    ELSE c.name
                END AS transaction_type,
            trns.transactionstatus,
            trns.channelid,
            ch.name AS channel_name,
            cybr.cycsauthtokenresponsejson::json ->> 'id'::text AS cybersource_trns_id,
                CASE
                    WHEN trns.chargebackofid IS NULL THEN cbspool.counterpartynarrativecr
                    ELSE cbspool.counterpartynarrativecr_rev
                END AS narrative,
                CASE
                    WHEN trns.chargebackofid IS NULL THEN cbspool.accountnumber
                    ELSE cbspool.accountnumber_rev
                END AS debit_gl_ac_no,
                CASE
                    WHEN trns.chargebackofid IS NULL THEN cbspool.accountnumbercr
                    ELSE cbspool.accountnumbercr_rev
                END AS credit_gl_ac_no,
            trns.description
           FROM ( SELECT wallettransactions.executionid,
                    wallettransactions.transactionid,
                    wallettransactions.businesstrxid,
                    wallettransactions.fromortouserid,
                    wallettransactions.debitamount,
                    wallettransactions.creditamount,
                    wallettransactions.pairid,
                    wallettransactions.createdon,
                    wallettransactions.businessproductid,
                    wallettransactions.parentid,
                    wallettransactions.transactionstatus,
                    wallettransactions.wallettypeid,
                    wallettransactions.channelid,
                    wallettransactions.description,
                    wallettransactions.instancetype,
                    wallettransactions.chargebackofid
                   FROM wallettransactions
                  WHERE wallettransactions.debitamount > 0::numeric
                UNION ALL
                 SELECT pendingtransaction.executionid,
                    NULL::character varying AS transactionid,
                    NULL::character varying AS businesstrxid,
                    pendingtransaction.fromuser AS fromortouserid,
                    pendingtransaction.debitreservedamount AS debitamount,
                    pendingtransaction.creditreservedamount AS creditamount,
                    NULL::character varying AS pairid,
                    pendingtransaction.createdon,
                    pendingtransaction.businessproductid,
                    NULL::character varying AS parentid,
                    pendingtransaction.transactionstatus,
                    pendingtransaction.creditwallettypeid AS wallettypeid,
                    pendingtransaction.channelid,
                    pendingtransaction.description,
                    NULL::character varying AS instancetype,
                    NULL::character varying AS chargebackofid
                   FROM pendingtransaction) trns
             LEFT JOIN users usr ON usr.id::text = trns.fromortouserid::text
             LEFT JOIN wallettype wtype ON wtype.id::text = trns.wallettypeid::text
             LEFT JOIN businessproduct bp ON bp.id::text = trns.businessproductid::text
             LEFT JOIN charges c ON c.id::text = trns.businessproductid::text
             LEFT JOIN channel ch ON ch.id::text = trns.channelid::text
             LEFT JOIN cybersourcetopup cybr ON cybr.referencecode::text = trns.executionid::text
             LEFT JOIN cbspool ON cbspool.productid::text = trns.businessproductid::text
             LEFT JOIN role rl ON rl.id::text = usr.roleid::text) dr
     JOIN ( SELECT trns.executionid,
            trns.transactionid,
            trns.businesstrxid,
            trns.fromortouserid,
                CASE
                    WHEN lower(trns.instancetype::text) ~~ '%business%'::text THEN wtype.name
                    ELSE COALESCE(usr.username, wtype.name)
                END AS username,
            rl.name AS rolename,
            trns.creditamount,
            trns.pairid,
            trns.createdon,
            trns.businessproductid AS trns_type_id,
                CASE
                    WHEN trns.parentid IS NULL THEN bp.name
                    ELSE c.name
                END AS transaction_type,
            trns.transactionstatus,
            trns.channelid,
            ch.name AS channel_name,
            cybr.cycsauthtokenresponsejson::json ->> 'id'::text AS cybersource_trns_id,
                CASE
                    WHEN trns.chargebackofid IS NULL THEN cbspool.counterpartynarrativecr
                    ELSE cbspool.counterpartynarrativecr_rev
                END AS narrative,
                CASE
                    WHEN trns.chargebackofid IS NULL THEN cbspool.accountnumber
                    ELSE cbspool.accountnumber_rev
                END AS debit_gl_ac_no,
                CASE
                    WHEN trns.chargebackofid IS NULL THEN cbspool.accountnumbercr
                    ELSE cbspool.accountnumbercr_rev
                END AS credit_gl_ac_no,
            trns.description
           FROM ( SELECT wallettransactions.executionid,
                    wallettransactions.transactionid,
                    wallettransactions.businesstrxid,
                    wallettransactions.fromortouserid,
                    wallettransactions.debitamount,
                    wallettransactions.creditamount,
                    wallettransactions.pairid,
                    wallettransactions.createdon,
                    wallettransactions.businessproductid,
                    wallettransactions.parentid,
                    wallettransactions.transactionstatus,
                    wallettransactions.wallettypeid,
                    wallettransactions.channelid,
                    wallettransactions.description,
                    wallettransactions.instancetype,
                    wallettransactions.chargebackofid
                   FROM wallettransactions
                  WHERE wallettransactions.creditamount > 0::numeric
                UNION ALL
                 SELECT pendingtransaction.executionid,
                    NULL::character varying AS transactionid,
                    NULL::character varying AS businesstrxid,
                    pendingtransaction.touser AS fromortouserid,
                    pendingtransaction.debitreservedamount AS debitamount,
                    pendingtransaction.creditreservedamount AS creditamount,
                    NULL::character varying AS pairid,
                    pendingtransaction.createdon,
                    pendingtransaction.businessproductid,
                    NULL::character varying AS parentid,
                    pendingtransaction.transactionstatus,
                    pendingtransaction.creditwallettypeid AS wallettypeid,
                    pendingtransaction.channelid,
                    pendingtransaction.description,
                    NULL::character varying AS instancetype,
                    NULL::character varying AS chargebackofid
                   FROM pendingtransaction) trns
             LEFT JOIN users usr ON usr.id::text = trns.fromortouserid::text
             LEFT JOIN wallettype wtype ON wtype.id::text = trns.wallettypeid::text
             LEFT JOIN businessproduct bp ON bp.id::text = trns.businessproductid::text
             LEFT JOIN charges c ON c.id::text = trns.businessproductid::text
             LEFT JOIN channel ch ON ch.id::text = trns.channelid::text
             LEFT JOIN cybersourcetopup cybr ON cybr.referencecode::text = trns.executionid::text
             LEFT JOIN cbspool ON cbspool.productid::text = trns.businessproductid::text
             LEFT JOIN role rl ON rl.id::text = usr.roleid::text) cr ON cr.executionid::text = dr.executionid::text AND cr.businesstrxid::text = dr.businesstrxid::text AND cr.creditamount = dr.debitamount
  ORDER BY dr.createdon DESC;


-- dashboard.registration_performance_report source

CREATE OR REPLACE VIEW dashboard.registration_performance_report
AS SELECT (users.firstname::text || ' '::text) || users.lastname::text AS "Name",
    users.mobilenumber AS "Mobile No.",
    users.idtype AS "ID Type",
    users.idnumber AS "ID Number",
    users.username AS "Customer Username",
        CASE
            WHEN users.walletfunded = true THEN 'Yes'::text
            WHEN users.walletfunded = false THEN 'No'::text
            ELSE 'NULL'::text
        END AS "Wallet Funded",
    to_char(users.firstfundingdate, 'yyyy-mm-dd HH24:MI:SS'::text) AS "First Fundingdate",
    users.fundingsource AS "Funding Score",
    users.roletype AS "Role",
    users.location AS "Location",
    users.userstatus AS "User Status",
    oper.username AS "Operator Username",
    users.createdby AS "Created By"
   FROM users
     JOIN users oper ON users.createdby::text = oper.id::text
  WHERE users.roletype::text = 'CUSTOMER'::text
  ORDER BY users.createdon;


-- dashboard.salary_disbursment source

CREATE OR REPLACE VIEW dashboard.salary_disbursment
AS SELECT s.sourceoffund AS "Source of Fund",
    s.merchantname AS " Merchant Name",
    s.merchantusername AS "Merchant Username",
    s.merchantregistrationnumber AS "Registration Number",
    s.merchantmobilenumber AS "Merchant Mobile Number",
    s.merchantlocation AS "Merchant Location",
    s.employeeusername AS "Employee UserName",
    s.employeemobilenumber AS "Employee Mobile Number",
    s.transactionstatus AS "Transaction Status",
    s.executionid AS "Transaction ID",
    to_char(s.txtime, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Transaction Timestamp",
    s.amount AS "Disbursed Amount",
    s.executionerror AS "Remarks",
    s.validationstatus AS "Validation Status",
    s.executionstatus AS "Execution Status"
   FROM salarydisbursementtxdetail s
  WHERE s.validationstatus::text = 'VALIDATED_SUCCESS'::text
  ORDER BY (to_char(s.txtime, 'yyyy-mm-dd HH24:MI:SS'::text)) DESC;


-- dashboard.saving_accounts source

CREATE OR REPLACE VIEW dashboard.saving_accounts
AS SELECT usr.username AS "Client ID",
    rdpa.rdaccountno AS "Account ID",
    usr.username AS "Mobile No.",
    concat(usr.firstname, ' ', usr.lastname) AS "Account Name",
    rdp.productnumber AS "Product ID",
    round(rdpa.totalamountdeposited, 2)::text AS "Account Balance",
    rdpa.createdon::timestamp(0) without time zone AS "Created on",
    usr.userstatus AS "Account Status",
    '1'::text AS "No. of Goals",
    rdpa.accountstatus AS "Is Active",
    round(rdpa.targetamount, 2)::text AS "Target Amount",
    rdpa.savingperiod AS "Savings Term (In Months)"
   FROM rdproductassociation rdpa
     LEFT JOIN users usr ON rdpa.userid::text = usr.id::text
     LEFT JOIN rdproduct rdp ON rdpa.productid::text = rdp.id::text;


-- dashboard.settlement source

CREATE OR REPLACE VIEW dashboard.settlement
AS SELECT DISTINCT t.description AS "Description",
    u.username AS "Merchant Account",
    u.firstname AS "Merchant Account Name",
    NULL::text AS "Sort Code",
    ac.accountnumber AS "Bank Account",
    1 AS "Type",
    73 AS "Code",
    72 AS "Currency",
    u.roletype AS "Role Type",
    r.name AS "Role Name"
   FROM users u
     LEFT JOIN role r ON r.id::text = u.roleid::text
     LEFT JOIN useraccounts ac ON ac.userid::text = u.id::text
     LEFT JOIN wallettransactions t ON t.fromortouserid::text = u.id::text
  WHERE lower(u.roletype::text) ~~ '%business%'::text AND lower(r.name::text) ~~ '%merch%'::text AND (lower(t.description::text) ~~ '%cash%'::text OR lower(t.description::text) ~~ '%purchase%'::text);


-- dashboard.transaction_agg source

CREATE OR REPLACE VIEW dashboard.transaction_agg
AS SELECT cr.executionid,
    cr.businesstrxid AS transaction_id,
    dr.username AS payer,
    cr.username AS payee,
    round(dr.debitamount, 2) AS amount,
    to_char(dr.createdon, 'yyyy-mm-dd HH24:MI:SS'::text) AS transaction_date,
    COALESCE(dr.transaction_type, dr.description) AS transaction_type,
    dr.transactionstatus AS transaction_status,
    dr.channel_name,
    dr.rolename AS payer_role,
    cr.rolename AS payee_role,
    dr.description
   FROM ( SELECT trns.executionid,
            trns.businesstrxid,
            trns.fromortouserid,
                CASE
                    WHEN lower(trns.instancetype::text) ~~ '%business%'::text THEN wtype.name
                    ELSE usr.username
                END AS username,
                CASE
                    WHEN lower(trns.instancetype::text) ~~ '%business%'::text THEN NULL::character varying
                    ELSE rl.name
                END AS rolename,
            trns.debitamount,
            trns.pairid,
            trns.createdon,
            trns.businessproductid AS trns_type_id,
                CASE
                    WHEN trns.parentid IS NULL THEN bp.name
                    ELSE c.name
                END AS transaction_type,
            trns.transactionstatus,
            trns.channelid,
            ch.name AS channel_name,
            trns.description
           FROM ( SELECT wallettransactions.executionid,
                    wallettransactions.businesstrxid,
                        CASE
                            WHEN wallettransactions.instancetype::text = 'CUSTOMER'::text AND (wallettransactions.fromortouserid::text = ''::text OR wallettransactions.fromortouserid IS NULL) THEN wallettransactions.ownerid
                            ELSE wallettransactions.fromortouserid
                        END AS fromortouserid,
                    wallettransactions.debitamount,
                    wallettransactions.creditamount,
                    wallettransactions.pairid,
                    wallettransactions.createdon,
                    wallettransactions.businessproductid,
                    wallettransactions.parentid,
                    wallettransactions.transactionstatus,
                    wallettransactions.wallettypeid,
                    wallettransactions.channelid,
                    wallettransactions.description,
                    wallettransactions.instancetype
                   FROM wallettransactions
                  WHERE wallettransactions.debitamount > 0::numeric
                UNION ALL
                 SELECT pendingtransaction.executionid,
                    NULL::character varying AS businesstrxid,
                    pendingtransaction.fromuser AS fromortouserid,
                    pendingtransaction.debitreservedamount AS debitamount,
                    pendingtransaction.creditreservedamount AS creditamount,
                    NULL::character varying AS pairid,
                    pendingtransaction.createdon,
                    pendingtransaction.businessproductid,
                    NULL::character varying AS parentid,
                    pendingtransaction.transactionstatus,
                    pendingtransaction.creditwallettypeid AS wallettypeid,
                    pendingtransaction.channelid,
                    pendingtransaction.description,
                    NULL::character varying AS instancetype
                   FROM pendingtransaction) trns
             LEFT JOIN users usr ON usr.id::text = trns.fromortouserid::text
             LEFT JOIN wallettype wtype ON wtype.id::text = trns.wallettypeid::text
             LEFT JOIN businessproduct bp ON bp.id::text = trns.businessproductid::text
             LEFT JOIN charges c ON c.id::text = trns.businessproductid::text
             LEFT JOIN channel ch ON ch.id::text = trns.channelid::text
             LEFT JOIN role rl ON rl.id::text = usr.roleid::text) dr
     JOIN ( SELECT trns.executionid,
            trns.businesstrxid,
            trns.fromortouserid,
                CASE
                    WHEN lower(trns.instancetype::text) ~~ '%business%'::text THEN wtype.name
                    ELSE usr.username
                END AS username,
                CASE
                    WHEN lower(trns.instancetype::text) ~~ '%business%'::text THEN NULL::character varying
                    ELSE rl.name
                END AS rolename,
            trns.creditamount,
            trns.pairid,
            trns.createdon,
            trns.businessproductid AS trns_type_id,
                CASE
                    WHEN trns.parentid IS NULL THEN bp.name
                    ELSE c.name
                END AS transaction_type,
            trns.transactionstatus,
            trns.channelid,
            ch.name AS channel_name,
            trns.description
           FROM ( SELECT wallettransactions.executionid,
                    wallettransactions.businesstrxid,
                        CASE
                            WHEN wallettransactions.instancetype::text = 'CUSTOMER'::text AND (wallettransactions.fromortouserid::text = ''::text OR wallettransactions.fromortouserid IS NULL) THEN wallettransactions.ownerid
                            ELSE wallettransactions.fromortouserid
                        END AS fromortouserid,
                    wallettransactions.debitamount,
                    wallettransactions.creditamount,
                    wallettransactions.pairid,
                    wallettransactions.createdon,
                    wallettransactions.businessproductid,
                    wallettransactions.parentid,
                    wallettransactions.transactionstatus,
                    wallettransactions.wallettypeid,
                    wallettransactions.channelid,
                    wallettransactions.description,
                    wallettransactions.instancetype
                   FROM wallettransactions
                  WHERE wallettransactions.creditamount > 0::numeric
                UNION ALL
                 SELECT pendingtransaction.executionid,
                    NULL::character varying AS businesstrxid,
                    pendingtransaction.touser AS fromortouserid,
                    pendingtransaction.debitreservedamount AS debitamount,
                    pendingtransaction.creditreservedamount AS creditamount,
                    NULL::character varying AS pairid,
                    pendingtransaction.createdon,
                    pendingtransaction.businessproductid,
                    NULL::character varying AS parentid,
                    pendingtransaction.transactionstatus,
                    pendingtransaction.creditwallettypeid AS wallettypeid,
                    pendingtransaction.channelid,
                    pendingtransaction.description,
                    NULL::character varying AS instancetype
                   FROM pendingtransaction) trns
             LEFT JOIN users usr ON usr.id::text = trns.fromortouserid::text
             LEFT JOIN wallettype wtype ON wtype.id::text = trns.wallettypeid::text
             LEFT JOIN businessproduct bp ON bp.id::text = trns.businessproductid::text
             LEFT JOIN charges c ON c.id::text = trns.businessproductid::text
             LEFT JOIN channel ch ON ch.id::text = trns.channelid::text
             LEFT JOIN role rl ON rl.id::text = usr.roleid::text) cr ON cr.executionid::text = dr.executionid::text AND cr.businesstrxid::text = dr.businesstrxid::text AND cr.creditamount = dr.debitamount
  ORDER BY dr.createdon DESC;


-- dashboard.transactions_summary source

CREATE OR REPLACE VIEW dashboard.transactions_summary
AS SELECT u.country,
    bp.name AS service_name,
    trns.transactionstatus AS trns_status,
        CASE
            WHEN trns.creditamount > 0::numeric THEN 'Credit'::text
            WHEN trns.debitamount > 0::numeric THEN 'Debit'::text
            ELSE NULL::text
        END AS trns_type,
    count(trns.transactionid) AS no_of_transactions,
    round(sum(trns.creditamount + trns.debitamount), 2) AS total_transacted_amount
   FROM wallettransactions trns
     LEFT JOIN businessproduct bp ON bp.id::text = trns.businessproductid::text
     LEFT JOIN users u ON u.id::text = trns.fromortouserid::text
  GROUP BY u.country, bp.name, trns.transactionstatus, (
        CASE
            WHEN trns.creditamount > 0::numeric THEN 'Credit'::text
            WHEN trns.debitamount > 0::numeric THEN 'Debit'::text
            ELSE NULL::text
        END);


-- dashboard.trial_balance_historical source

CREATE OR REPLACE VIEW dashboard.trial_balance_historical
AS SELECT DISTINCT ON ((coatrailbalancedata.createdon::date), coatrailbalancedata.name) coatrailbalancedata.createdon::date AS createdon,
    coatrailbalancedata.name AS "Name",
    round(coatrailbalancedata.creditamount, 2) AS "Credit Amount",
    round(coatrailbalancedata.debitamount, 2) AS "Debit Amount",
    round(coatrailbalancedata.balance, 2) AS "Balance",
    coatrailbalancedata.glaccountnumber AS "GL Account No."
   FROM coatrailbalancedata;


-- dashboard.user_activity_report source

CREATE OR REPLACE VIEW dashboard.user_activity_report
AS SELECT to_char(u1.createdon, 'yyyy-mm-dd HH24:MI:SS'::text) AS createdon,
    u1.mobilenumber AS "Mobile Number",
    u1.userstatus AS "User Status",
    b.username,
    b."Airtime Purchase",
    b."Bill Payment",
    b."Withdrawal (Wallet to Bank & ATM Cash out)",
    b."Deposit (Card top-up and Bank to wallet)",
    b."Transfers (QR Pay, Send Money)",
    b."Wallet on POS",
    b."Cash in & Cash out"
   FROM users u1
     JOIN ( SELECT ct.username,
            ct."Airtime Purchase",
            ct."Bill Payment",
            ct."Withdrawal (Wallet to Bank & ATM Cash out)",
            ct."Deposit (Card top-up and Bank to wallet)",
            ct."Transfers (QR Pay, Send Money)",
            ct."Wallet on POS",
            ct."Cash in & Cash out"
           FROM crosstab('select users.username,subcategory.name as "Business Activity",

concat(''Count:'',usertransactionslabdata.fromcount, ''-'', usertransactionslabdata.tocount, ''-'', usertransactionslabdata.countother, '' | Amount :''

,usertransactionslabdata.fromamount, ''-'', usertransactionslabdata.toamount) as "Amount"

from usertransactionslabdata

left join subcategory on usertransactionslabdata.subcategoryid = subcategory.id

left join users on users.id =usertransactionslabdata.userid'::text) ct(username character varying, "Airtime Purchase" text, "Bill Payment" text, "Withdrawal (Wallet to Bank & ATM Cash out)" text, "Deposit (Card top-up and Bank to wallet)" text, "Transfers (QR Pay, Send Money)" text, "Wallet on POS" text, "Cash in & Cash out" text)) b ON b.username::text = u1.username::text;


-- dashboard.user_info_view source

CREATE OR REPLACE VIEW dashboard.user_info_view
AS SELECT row_number() OVER () AS "Sr. No.",
    u.username AS "User Name",
    r.name AS "Role Name",
    u.firstname AS "First Name",
    u.middlename AS "Middle Name",
    u.lastname AS "Last Name",
    u.mobilenumber AS "mobile No.",
    to_char(u.createdon, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Registration Date",
    u.email AS "Email",
    to_char(u.dob, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Date of Birth",
    u.gender AS "Gender",
    u.address AS "Address",
    u.country AS "Country",
    u.countrycode AS "Country Code",
    to_char(u.passwordexpirydate, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Password Exipry Date",
    u.state AS "State",
    u.city AS "City",
    u.pincode AS "City Pincode",
    u.userstatus AS "Status",
    u.roletype AS "Role Type",
    u.idtype AS "ID Type",
    u.idnumber AS "ID Number"
   FROM users u
     LEFT JOIN role r ON u.roleid::text = r.id::text;


-- dashboard.user_kyc_info source

CREATE OR REPLACE VIEW dashboard.user_kyc_info
AS SELECT row_number() OVER () AS sno,
    u.id,
    u.createdby,
    u.username,
    u.firstname,
    u.middlename,
    u.lastname,
    u.mobilenumber,
    u.createdon AS registrationdate,
    u.email,
    u.dob AS dateofbirth,
    u.gender,
    u.address,
    u.countrycode,
    u.state,
    u.pincode AS citypincode,
    u.userstatus AS status,
    u.roletype,
    r.name AS rolename,
    urf.referredby,
    ukc.kycdocumenttype,
    ukc.kycprooftype,
    ukc.kycdocumentlistjson,
    ( SELECT each_attr.value ->> 'orignalFileName'::text AS kycdocumentname
           FROM userkyc
             CROSS JOIN unnest(ARRAY[ukc.kycdocumentlistjson::json]) each_doc(each_doc)
             CROSS JOIN LATERAL json_array_elements(each_doc.each_doc) each_attr(value)
          WHERE userkyc.userid::text = u.id::text
          ORDER BY (each_attr.value ->> 'uploadedOn'::text) DESC
         LIMIT 1) AS kycdocumentname,
    ( SELECT count(*) AS kycdocumentversion
           FROM userkyc
             CROSS JOIN unnest(ARRAY[ukc.kycdocumentlistjson::json]) each_doc(each_doc)
             CROSS JOIN LATERAL json_array_elements(each_doc.each_doc) each_attr(value)
          WHERE userkyc.userid::text = u.id::text) AS kycdocumentversion,
    uekycad.createdon AS kycupgraderequestdate,
    uekycad.modifiedon AS kycapproverequestdate,
    uekycad.kycapproveruser,
    nu.username AS registeredbyagent
   FROM users u
     LEFT JOIN ( SELECT urf_1.referraluserid,
            urf_1.refereeuserid,
            u_1.username AS referredby
           FROM userreferral urf_1
             LEFT JOIN users u_1 ON u_1.id::text = urf_1.refereeuserid::text) urf ON u.id::text = urf.referraluserid::text
     LEFT JOIN userkyc ukc ON u.id::text = ukc.userid::text
     LEFT JOIN role r ON u.roleid::text = r.id::text
     LEFT JOIN ( SELECT u_1.username AS usrname,
            uekycad_1.username,
            uekycad_1.kycstatus,
            uekycad_1.createdby,
            uekycad_1.createdon,
            uekycad_1.modifiedon,
            ( SELECT users.username
                   FROM users
                  WHERE users.id::text = uekycad_1.modifiedby::text) AS kycapproveruser
           FROM userenhancekycaudit uekycad_1
             LEFT JOIN users u_1 ON u_1.id::text = uekycad_1.createdby::text
          WHERE uekycad_1.kycstatus::text = 'APPROVED'::text) uekycad ON u.id::text = uekycad.createdby::text
     LEFT JOIN ( SELECT nu_1.createdby,
            nu_1.username,
            nu_1.id,
            r_1.name
           FROM users nu_1
             JOIN role r_1 ON nu_1.roleid::text = r_1.id::text AND (r_1.name::text = 'AgentUser'::text OR r_1.name::text = 'Agent'::text OR r_1.name::text = 'Absa Agent'::text)) nu ON u.createdby::text = nu.id::text;


-- dashboard.user_transaction source

CREATE OR REPLACE VIEW dashboard.user_transaction
AS SELECT cr.businesstrxid AS "Transaction ID",
    dr.username AS "Payer",
    cr.username AS "Payee",
    dr."Created By",
    round(dr.debitamount, 2) AS "Amount",
    to_char(dr.txtime, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Transaction Date",
    COALESCE(dr.transaction_type, dr.description) AS "TransactionType",
    dr.transactionstatus AS "Transaction Status",
    dr.channel_name AS "Channel",
    dr.rolename AS "Payer Role",
    cr.rolename AS "Payee Role",
    dr.description AS "Description",
    dr.remarks AS "Remarks",
    cr.reference AS "Reference",
    dr.remarks AS "Voucher Details",
    dr.idtype AS "ID Type",
    dr.idnumber AS "ID Number",
    cr.roletype AS "Role",
    cr.mobilenumber AS "Mobile No.",
    cr.transactiontype AS "Transaction Type",
    cr.depositorname AS "Depositor Name",
    dr.location AS "Location",
    dr.firstname AS "From User",
    cr.firstname AS "To User",
    cr.consumeruniquereferenceid AS "Consumer Unique Reference ID"
   FROM ( SELECT trns.executionid,
            trns.businesstrxid,
            trns.fromortouserid,
                CASE
                    WHEN lower(trns.instancetype::text) ~~ '%business%'::text THEN wtype.name
                    ELSE usr.username
                END AS username,
                CASE
                    WHEN lower(trns.instancetype::text) ~~ '%business%'::text THEN NULL::character varying
                    ELSE rl.name
                END AS rolename,
            trns.debitamount,
            trns.pairid,
            trns.txtime,
            trns.businessproductid AS trns_type_id,
                CASE
                    WHEN trns.parentid IS NULL THEN bp.name
                    ELSE c.name
                END AS transaction_type,
            trns.transactionstatus,
            trns.channelid,
            ch.name AS channel_name,
            trns.description,
            trns.remarks,
            wtx.reference,
            usr.roletype,
            usr.mobilenumber,
            usr.location,
            usr.firstname,
            trns.idtype,
            trns.idnumber,
            bp.transactiontype,
            trns.depositorname,
                CASE
                    WHEN subx.username IS NULL THEN 'SYSTEM'::character varying
                    WHEN usr.registrationviaweb IS FALSE THEN usr.username
                    ELSE subx.username
                END AS "Created By",
            uservouchercodes.remarks AS "Voucher Details",
            billpaymenttxdetails.consumeruniquereferenceid
           FROM ( SELECT wallettransactions.executionid,
                    wallettransactions.businesstrxid,
                        CASE
                            WHEN wallettransactions.instancetype::text = 'CUSTOMER'::text AND (wallettransactions.fromortouserid::text = ''::text OR wallettransactions.fromortouserid IS NULL) THEN wallettransactions.ownerid
                            ELSE wallettransactions.fromortouserid
                        END AS fromortouserid,
                    wallettransactions.debitamount,
                    wallettransactions.creditamount,
                    wallettransactions.pairid,
                    wallettransactions.txtime,
                    wallettransactions.businessproductid,
                    wallettransactions.parentid,
                    wallettransactions.transactionstatus,
                    wallettransactions.wallettypeid,
                    wallettransactions.channelid,
                    wallettransactions.description,
                    wallettransactions.instancetype,
                    wallettransactions.remarks,
                    wallettransactions.depositorname,
                    wallettransactions.idtype,
                    wallettransactions.idnumber,
                    wallettransactions.initiatorid,
                    uservouchercodes_1.remarks AS "Voucher Details",
                    billpaymenttxdetails_1.consumeruniquereferenceid
                   FROM wallettransactions
                     LEFT JOIN uservouchercodes uservouchercodes_1 ON uservouchercodes_1.txid::text = wallettransactions.businesstrxid::text
                     LEFT JOIN billpaymenttxdetails billpaymenttxdetails_1 ON billpaymenttxdetails_1.executionid::text = wallettransactions.executionid::text
                  WHERE wallettransactions.debitamount > 0::numeric
                UNION ALL
                 SELECT pendingtransaction.executionid,
                    NULL::character varying AS businesstrxid,
                    pendingtransaction.fromuser AS fromortouserid,
                    pendingtransaction.debitreservedamount AS debitamount,
                    pendingtransaction.creditreservedamount AS creditamount,
                    NULL::character varying AS pairid,
                    pendingtransaction.txtime,
                    pendingtransaction.businessproductid,
                    NULL::character varying AS parentid,
                    pendingtransaction.transactionstatus,
                    pendingtransaction.creditwallettypeid AS wallettypeid,
                    pendingtransaction.channelid,
                    pendingtransaction.description,
                    NULL::character varying AS instancetype,
                    pendingtransaction.remarks,
                    NULL::character varying AS depositorname,
                    NULL::character varying AS idtype,
                    NULL::character varying AS idnumber,
                    NULL::character varying AS initiatorid,
                    NULL::character varying AS "Voucher Details",
                    NULL::character varying AS "Consumer Unique Reference ID"
                   FROM pendingtransaction
                  WHERE pendingtransaction.transactionstatus::text <> 'AUTHORIZED'::text) trns
             LEFT JOIN users usr ON usr.id::text = trns.fromortouserid::text
             LEFT JOIN wallettype wtype ON wtype.id::text = trns.wallettypeid::text
             LEFT JOIN businessproduct bp ON bp.id::text = trns.businessproductid::text
             LEFT JOIN charges c ON c.id::text = trns.businessproductid::text
             LEFT JOIN channel ch ON ch.id::text = trns.channelid::text
             LEFT JOIN wallettobanktxdetails wtx ON wtx.executionid::text = trns.executionid::text
             LEFT JOIN role rl ON rl.id::text = usr.roleid::text
             LEFT JOIN billpaymenttxdetails ON billpaymenttxdetails.executionid::text = trns.executionid::text
             LEFT JOIN uservouchercodes ON uservouchercodes.txid::text = trns.businesstrxid::text
             LEFT JOIN ( SELECT a.id,
                    b.username
                   FROM users a
                     JOIN users b ON b.id::text = a.createdby::text) subx ON trns.initiatorid::text = subx.id::text) dr
     JOIN ( SELECT trns.executionid,
            trns.businesstrxid,
            trns.fromortouserid,
                CASE
                    WHEN lower(trns.instancetype::text) ~~ '%business%'::text THEN wtype.name
                    ELSE usr.username
                END AS username,
                CASE
                    WHEN lower(trns.instancetype::text) ~~ '%business%'::text THEN NULL::character varying
                    ELSE rl.name
                END AS rolename,
            trns.creditamount,
            trns.pairid,
            trns.txtime,
            trns.businessproductid AS trns_type_id,
                CASE
                    WHEN trns.parentid IS NULL THEN bp.name
                    ELSE c.name
                END AS transaction_type,
            trns.transactionstatus,
            trns.channelid,
            ch.name AS channel_name,
            trns.description,
            trns.remarks,
            wtx.reference,
            usr.roletype,
            usr.mobilenumber,
            usr.idtype,
            usr.idnumber,
            usr.location,
            usr.firstname,
            bp.transactiontype,
            trns.depositorname,
                CASE
                    WHEN subx.username IS NULL THEN 'SYSTEM'::character varying
                    WHEN usr.registrationviaweb IS FALSE THEN usr.username
                    ELSE subx.username
                END AS "Created By",
            uservouchercodes.remarks AS "Voucher Details",
            billpaymenttxdetails.consumeruniquereferenceid
           FROM ( SELECT wallettransactions.executionid,
                    wallettransactions.businesstrxid,
                        CASE
                            WHEN wallettransactions.instancetype::text = 'CUSTOMER'::text AND (wallettransactions.fromortouserid::text = ''::text OR wallettransactions.fromortouserid IS NULL) THEN wallettransactions.ownerid
                            ELSE wallettransactions.fromortouserid
                        END AS fromortouserid,
                    wallettransactions.debitamount,
                    wallettransactions.creditamount,
                    wallettransactions.pairid,
                    wallettransactions.txtime,
                    wallettransactions.businessproductid,
                    wallettransactions.parentid,
                    wallettransactions.transactionstatus,
                    wallettransactions.wallettypeid,
                    wallettransactions.channelid,
                    wallettransactions.description,
                    wallettransactions.instancetype,
                    wallettransactions.remarks,
                    wallettransactions.depositorname,
                    wallettransactions.idtype,
                    wallettransactions.idnumber,
                    wallettransactions.initiatorid,
                    uservouchercodes_1.remarks AS "Voucher Details",
                    billpaymenttxdetails_1.consumeruniquereferenceid
                   FROM wallettransactions
                     LEFT JOIN uservouchercodes uservouchercodes_1 ON uservouchercodes_1.txid::text = wallettransactions.businesstrxid::text
                     LEFT JOIN billpaymenttxdetails billpaymenttxdetails_1 ON billpaymenttxdetails_1.executionid::text = wallettransactions.executionid::text
                  WHERE wallettransactions.creditamount > 0::numeric
                UNION ALL
                 SELECT pendingtransaction.executionid,
                    NULL::character varying AS businesstrxid,
                    pendingtransaction.touser AS fromortouserid,
                    pendingtransaction.debitreservedamount AS debitamount,
                    pendingtransaction.creditreservedamount AS creditamount,
                    NULL::character varying AS pairid,
                    pendingtransaction.txtime,
                    pendingtransaction.businessproductid,
                    NULL::character varying AS parentid,
                    pendingtransaction.transactionstatus,
                    pendingtransaction.creditwallettypeid AS wallettypeid,
                    pendingtransaction.channelid,
                    pendingtransaction.description,
                    NULL::character varying AS instancetype,
                    pendingtransaction.remarks,
                    NULL::character varying AS depositorname,
                    NULL::character varying AS idtype,
                    NULL::character varying AS idnumber,
                    NULL::character varying AS initiatorid,
                    NULL::character varying AS "Voucher Details",
                    NULL::character varying AS "Consumer Unique Reference ID"
                   FROM pendingtransaction
                  WHERE pendingtransaction.transactionstatus::text <> 'AUTHORIZED'::text) trns
             LEFT JOIN users usr ON usr.id::text = trns.fromortouserid::text
             LEFT JOIN wallettype wtype ON wtype.id::text = trns.wallettypeid::text
             LEFT JOIN businessproduct bp ON bp.id::text = trns.businessproductid::text
             LEFT JOIN charges c ON c.id::text = trns.businessproductid::text
             LEFT JOIN channel ch ON ch.id::text = trns.channelid::text
             LEFT JOIN wallettobanktxdetails wtx ON wtx.executionid::text = trns.executionid::text
             LEFT JOIN role rl ON rl.id::text = usr.roleid::text
             LEFT JOIN billpaymenttxdetails ON billpaymenttxdetails.executionid::text = trns.executionid::text
             LEFT JOIN uservouchercodes ON uservouchercodes.txid::text = trns.businesstrxid::text
             LEFT JOIN ( SELECT a.id,
                    b.username
                   FROM users a
                     JOIN users b ON b.id::text = a.createdby::text) subx ON subx.id::text = trns.initiatorid::text) cr ON cr.executionid::text = dr.executionid::text AND cr.creditamount = dr.debitamount
  ORDER BY dr.txtime DESC;


