-- public.information_schema_bw source

CREATE OR REPLACE VIEW public.information_schema_bw
AS SELECT columns.table_catalog,
    columns.table_schema,
    columns.table_name,
    columns.column_name,
    columns.ordinal_position,
    'bw'::text AS country
   FROM information_schema.columns
  WHERE columns.table_schema::name = ANY (ARRAY['public'::name, 'HadoopMigration'::name]);


-- public.pg_stat_statements source

CREATE OR REPLACE VIEW public.pg_stat_statements
AS SELECT pg_stat_statements.userid,
    pg_stat_statements.dbid,
    pg_stat_statements.queryid,
    pg_stat_statements.query,
    pg_stat_statements.calls,
    pg_stat_statements.total_time,
    pg_stat_statements.min_time,
    pg_stat_statements.max_time,
    pg_stat_statements.mean_time,
    pg_stat_statements.stddev_time,
    pg_stat_statements.rows,
    pg_stat_statements.shared_blks_hit,
    pg_stat_statements.shared_blks_read,
    pg_stat_statements.shared_blks_dirtied,
    pg_stat_statements.shared_blks_written,
    pg_stat_statements.local_blks_hit,
    pg_stat_statements.local_blks_read,
    pg_stat_statements.local_blks_dirtied,
    pg_stat_statements.local_blks_written,
    pg_stat_statements.temp_blks_read,
    pg_stat_statements.temp_blks_written,
    pg_stat_statements.blk_read_time,
    pg_stat_statements.blk_write_time
   FROM pg_stat_statements(true) pg_stat_statements(userid, dbid, queryid, query, calls, total_time, min_time, max_time, mean_time, stddev_time, rows, shared_blks_hit, shared_blks_read, shared_blks_dirtied, shared_blks_written, local_blks_hit, local_blks_read, local_blks_dirtied, local_blks_written, temp_blks_read, temp_blks_written, blk_read_time, blk_write_time);


-- public.user_info source

CREATE OR REPLACE VIEW public.user_info
AS SELECT row_number() OVER () AS slno,
    u.username,
    r.name AS rolename,
    u.firstname,
    u.middlename,
    u.lastname,
    u.mobilenumber,
    u.createdon AS registrationdate,
    u.email,
    u.dob AS dateofbirth,
    u.gender,
    u.address,
    u.country,
    u.countrycode,
    u.passwordexpirydate,
    u.state,
    u.city,
    u.pincode AS citypincode,
    u.userstatus AS status,
    u.roletype,
    u.idtype,
    u.idnumber
   FROM users u
     LEFT JOIN role r ON u.roleid::text = r.id::text;

