-- DROP FUNCTION public.absacodesfunc();

CREATE OR REPLACE FUNCTION public.absacodesfunc()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
      INSERT INTO "HadoopMigration".absacodes_hadoop(sequenceid, id, statuscode, description, codetype) 
            values 
      (nextval('absacodes_seq'), new.id,new.statuscode,new.description,new.codetype);
      RETURN NEW;
   END;
$function$
;

-- DROP FUNCTION public.absacodesupdatefunc();

CREATE OR REPLACE FUNCTION public.absacodesupdatefunc()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  UPDATE "HadoopMigration".absacodes_hadoop 
set 
statuscode=new.statuscode,
description=new.description,
codetype=new.codetype
where
id = new.id;
RETURN NEW;
   END;
$function$
;

