initiatorid=new.initiatorid,
instancetype=new.instancetype,
orignalrequestjson=new.orignalrequestjson,
otherwalletinstanceid=new.otherwalletinstanceid,
ownerid=new.ownerid,
producttype=new.producttype,
productusermappingid=new.productusermappingid,
sourceid=new.sourceid,
totalbalance=new.totalbalance,
totalcreditamount=new.totalcreditamount,
totaldebitamount=new.totaldebitamount,
walletinstanceid=new.walletinstanceid,
walletno=new.walletno,
walletstatus=new.walletstatus,
wallettypeid=new.wallettypeid
where
transactionid = new.transactionid;
RETURN NEW;
   END;
$function$
