-- DROP FUNCTION public.wallettypeupdatefunc();

CREATE OR REPLACE FUNCTION public.wallettypeupdatefunc()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  UPDATE "HadoopMigration".wallettype_hadoop 
set 
createdby=new.createdby,
createdon=new.createdon,
modifiedby=new.modifiedby,
modifiedon=new.modifiedon,
name=new.name,
name_key=new.name_key,
currencyid=new.currencyid,
description=new.description,
wallettype=new.wallettype,
internalwallet=new.internalwallet,
parentglid=new.parentglid,
glid=new.glid,
walletcode=new.walletcode,
upperlimit=new.upperlimit,
lowerlimit=new.lowerlimit,
approvalstatus=new.approvalstatus,
conversionparentgl=new.conversionparentgl,
coregltype=new.coregltype,
pendingvaluejson=new.pendingvaluejson,
postapprovalstatus=new.postapprovalstatus,
preapprovalstatus=new.preapprovalstatus,
remarks=new.remarks,
statuschangedby=new.statuschangedby,
statuschangedon=new.statuschangedon
where
id = new.id;
RETURN NEW;
   END;
$function$
